#[test]fn anonymous_function_expressions_and_calls(){let mut r=Runtime::new();assert_eq!(r.execute("let double=function(x){return x*2;};double(6);").unwrap(),Value::Number(12.0));assert_eq!(r.execute("(function(x){return x+1;})(8);").unwrap(),Value::Number(9.0));assert_eq!(r.execute("let apply=function(f,x){return f(x);};apply(function(n){return n*n;},5);").unwrap(),Value::Number(25.0));assert_eq!(r.execute("let make=function(x){return function(y){return x+y;};};let addFive=make(5);addFive(3);").unwrap(),Value::Number(8.0));}#[test]fn array_last_index_and_string_helpers(){let mut r=Runtime::new();assert_eq!(r.execute("[1,2,1,2].lastIndexOf(2);").unwrap(),Value::Number(3.0));assert_eq!(r.execute("[1,2,1,2].lastIndexOf(1,2);").unwrap(),Value::Number(2.0));assert_eq!(r.execute("[1,2,1].lastIndexOf(1,-2);").unwrap(),Value::Number(0.0));assert_eq!(r.execute("'hello'.startsWith('ell',1);").unwrap(),Value::Boolean(true));assert_eq!(r.execute("'hello'.endsWith('ell',4);").unwrap(),Value::Boolean(true));assert_eq!(r.execute("'hello'.indexOf('ll');").unwrap(),Value::Number(2.0));assert_eq!(r.execute("'ha'.repeat(3);").unwrap(),Value::String("hahaha".into()));assert_eq!(r.execute("'abcdef'.slice(1,4);").unwrap(),Value::String("bcd".into()));}#[test]fn array_find_last_methods(){let mut r=Runtime::new();assert_eq!(r.execute("function isEvenLast(x){return x%2==0;} [1,2,4,5].findLast(isEvenLast);").unwrap(),Value::Number(4.0));assert_eq!(r.execute("function isEvenIndex(x){return x%2==0;} [1,2,4,5].findLastIndex(isEvenIndex);").unwrap(),Value::Number(2.0));assert_eq!(r.execute("function isBigLast(x){return x>9;} [1,2,3].findLast(isBigLast);").unwrap(),Value::Undefined);assert_eq!(r.execute("function isBigIndex(x){return x>9;} [1,2,3].findLastIndex(isBigIndex);").unwrap(),Value::Number(-1.0));}#[test]fn array_fill_and_flat(){let mut r=Runtime::new();assert_eq!(r.execute("let a=[1,2,3,4];a.fill(9,1,3);a[1]*10+a[2];").unwrap(),Value::Number(99.0));assert_eq!(r.execute("[1,[2,3],[4,[5]]].flat().length;").unwrap(),Value::Number(5.0));assert_eq!(r.execute("[1,[2,3],[4,[5]]].flat(2).length;").unwrap(),Value::Number(5.0));assert_eq!(r.execute("[1,2,3].fill(7,-2)[1];").unwrap(),Value::Number(7.0));}#[test]fn array_splice_with_and_copying_methods(){let mut r=Runtime::new();assert_eq!(r.execute("let a=[1,2,3,4];let removed=a.splice(1,2,8,9);removed[0]*10+a[1];").unwrap(),Value::Number(28.0));assert_eq!(r.execute("let a=[1,2,3];let b=a.with(-1,9);b[2]*10+a[2];").unwrap(),Value::Number(93.0));assert_eq!(r.execute("let a=[1,2,3];let b=a.toSpliced(1,1,8);b[1]*10+a[1];").unwrap(),Value::Number(82.0));assert_eq!(r.execute("let a=[3,1,2];let b=a.toSorted();b[0]*10+a[0];").unwrap(),Value::Number(13.0));}#[test]fn array_sort_default_and_comparator(){let mut r=Runtime::new();assert_eq!(r.execute("[3,1,2].sort()[0];").unwrap(),Value::Number(1.0));assert_eq!(r.execute("[10,2,1].sort()[0];").unwrap(),Value::Number(1.0));assert_eq!(r.execute("function compare(a,b){return a-b;} [10,2,1].sort(compare)[2];").unwrap(),Value::Number(10.0));assert_eq!(r.execute("let a=[3,1,2];a.sort();a[2];").unwrap(),Value::Number(3.0));}#[test]fn array_flat(){let mut r=Runtime::new();assert_eq!(r.execute("[1,[2,[3]]].flat();").unwrap(),Value::Array(Rc::new(RefCell::new(vec![Value::Number(1.0),Value::Number(2.0),Value::Array(Rc::new(RefCell::new(vec![Value::Number(3.0)])))]))));assert_eq!(r.execute("[1,[2,[3]]].flat(2).length;").unwrap(),Value::Number(3.0));assert_eq!(r.execute("[1,[2]].flat(0).length;").unwrap(),Value::Number(2.0));}#[test]fn array_and_string_at_fill(){let mut r=Runtime::new();assert_eq!(r.execute("[10,20,30].at(-1);").unwrap(),Value::Number(30.0));assert_eq!(r.execute("let a=[1,2,3];a.fill(9,1);a[1]+a[2];").unwrap(),Value::Number(18.0));assert_eq!(r.execute("\"hello\".at(-1);").unwrap(),Value::String("o".into()));assert!(matches!(r.execute("[1].at(5);").unwrap(),Value::Undefined));}#[test]fn named_function_array_callbacks(){let mut r=Runtime::new();assert_eq!(r.execute("function twice(x){return x*2;} [1,2,3].map(twice)[2];").unwrap(),Value::Number(6.0));assert_eq!(r.execute("function positive(x){return x>0;} [ -1,0,2,3 ].filter(positive).length;").unwrap(),Value::Number(2.0));assert_eq!(r.execute("function positiveIndex(x){return x>0;} [ -1,0,2,3 ].findIndex(positiveIndex);").unwrap(),Value::Number(2.0));assert_eq!(r.execute("function add(a,b){return a+b;} [1,2,3].reduce(add,0);").unwrap(),Value::Number(6.0));assert_eq!(r.execute("function positiveEvery(x){return x>0;} [1,2,3].every(positiveEvery);").unwrap(),Value::Boolean(true));assert_eq!(r.execute("function positiveSome(x){return x>0;} [-1,2].some(positiveSome);").unwrap(),Value::Boolean(true));}#[test]fn object_from_entries(){let mut r=Runtime::new();assert_eq!(r.execute("Object.fromEntries([[\"a\",1],[\"b\",2]]).b;").unwrap(),Value::Number(2.0));assert_eq!(r.execute("Object.fromEntries([[\"x\",3]]).x;").unwrap(),Value::Number(3.0));assert!(r.execute("Object.fromEntries([1]);").is_err());assert!(r.execute("Object.fromEntries([[\"x\"]]);").is_err());}#[test]fn string_char_code_and_last_index(){let mut r=Runtime::new();assert_eq!(r.execute("\"ABC\".charCodeAt(1);").unwrap(),Value::Number(66.0));assert!(matches!(r.execute("\"A\".charCodeAt(9);").unwrap(),Value::Number(n) if n.is_nan()));assert_eq!(r.execute("\"banana\".lastIndexOf(\"an\");").unwrap(),Value::Number(3.0));assert_eq!(r.execute("\"banana\".lastIndexOf(\"an\",2);").unwrap(),Value::Number(1.0));assert_eq!(r.execute("\"banana\".lastIndexOf(\"\");").unwrap(),Value::Number(6.0));assert_eq!(r.execute("\"banana\".lastIndexOf(\"x\");").unwrap(),Value::Number(-1.0));}#[test]fn string_trim_edges_and_concat(){let mut r=Runtime::new();assert_eq!(r.execute("\"  hi  \".trimStart();").unwrap(),Value::String("hi  ".into()));assert_eq!(r.execute("\"  hi  \".trimEnd();").unwrap(),Value::String("  hi".into()));assert_eq!(r.execute("\"Hello\".concat(\" \",\"world\");").unwrap(),Value::String("Hello world".into()));}#[test]fn string_padding(){let mut r=Runtime::new();assert_eq!(r.execute("\"5\".padStart(3,\"0\");").unwrap(),Value::String("005".into()));assert_eq!(r.execute("\"x\".padEnd(4,\"ab\");").unwrap(),Value::String("xaba".into()));assert_eq!(r.execute("\"hello\".padStart(2);").unwrap(),Value::String("hello".into()));assert_eq!(r.execute("\"x\".padEnd(3,\"\");").unwrap(),Value::String("x".into()));}#[test]fn string_static_unicode_helpers(){let mut r=Runtime::new();assert_eq!(r.execute("String.fromCharCode(65,66,67);").unwrap(),Value::String("ABC".into()));assert_eq!(r.execute("String.fromCodePoint(128512);").unwrap(),Value::String("😀".into()));assert!(r.execute("String.fromCodePoint(1114112);").is_err());}#[test]fn math_log1p_expm1(){let mut r=Runtime::new();assert!((match r.execute("Math.log1p(0.5);").unwrap(){Value::Number(n)=>n,_=>panic!("expected number")}-0.4054651081081644).abs()<1e-14);assert!((match r.execute("Math.expm1(1);").unwrap(){Value::Number(n)=>n,_=>panic!("expected number")}-1.718281828459045).abs()<1e-14);assert_eq!(r.execute("Math.log1p(-1);").unwrap(),Value::Number(f64::NEG_INFINITY));assert!(matches!(r.execute("Math.log1p(-2);").unwrap(),Value::Number(n) if n.is_nan()));}#[test]fn math_nan_and_signed_zero_semantics(){let mut r=Runtime::new();assert!(matches!(r.execute("Math.max(1,NaN);").unwrap(),Value::Number(n) if n.is_nan()));assert!(matches!(r.execute("Math.min(1,NaN);").unwrap(),Value::Number(n) if n.is_nan()));assert!(matches!(r.execute("Math.round(-0.1);").unwrap(),Value::Number(n) if n==0.0&&n.is_sign_negative()));assert!(matches!(r.execute("Math.max(-0,0);").unwrap(),Value::Number(n) if n==0.0&&n.is_sign_positive()));assert!(matches!(r.execute("Math.min(-0,0);").unwrap(),Value::Number(n) if n==0.0&&n.is_sign_negative()));}#[test]fn math_32bit_helpers(){let mut r=Runtime::new();assert_eq!(r.execute("Math.clz32(1);").unwrap(),Value::Number(31.0));assert_eq!(r.execute("Math.clz32(0);").unwrap(),Value::Number(32.0));assert_eq!(r.execute("Math.imul(0xffffffff,5);").unwrap(),Value::Number(-5.0));assert_eq!(r.execute("Math.imul(3,7);").unwrap(),Value::Number(21.0));assert_eq!(r.execute("Math.fround(1.5);").unwrap(),Value::Number(1.5));}#[test]fn expanded_math_and_number_helpers(){let mut r=Runtime::new();assert_eq!(r.execute("Math.sin(0);").unwrap(),Value::Number(0.0));assert_eq!(r.execute("Math.log10(100);").unwrap(),Value::Number(2.0));assert_eq!(r.execute("Number.isInteger(4);").unwrap(),Value::Boolean(true));assert_eq!(r.execute("Number.isInteger(4.5);").unwrap(),Value::Boolean(false));assert_eq!(r.execute("Number.isNaN(NaN);").unwrap(),Value::Boolean(true));assert_eq!(r.execute("Array.isArray([1,2]);").unwrap(),Value::Boolean(true));assert_eq!(r.execute("Array.isArray({x:1});").unwrap(),Value::Boolean(false));let x=r.execute("Math.random();").unwrap();assert!(matches!(x,Value::Number(n) if n>=0.0&&n<1.0));}#[test]fn math_constants(){let mut r=Runtime::new();assert_eq!(r.execute("Math.PI;").unwrap(),Value::Number(std::f64::consts::PI));assert_eq!(r.execute("Math.E;").unwrap(),Value::Number(std::f64::consts::E));}#[test]fn switch_statements(){let mut r=Runtime::new();assert_eq!(r.execute("let x=2;let y=0;switch(x){case 1:y=10;break;case 2:y=20;case 3:y=y+1;break;default:y=99;}y;").unwrap(),Value::Number(21.0));assert_eq!(r.execute("let x=8;switch(x){case 1:1;break;default:7;}").unwrap(),Value::Number(7.0));}#[test]fn math_builtins(){let mut r=Runtime::new();assert_eq!(r.execute("Math.abs(-4);").unwrap(),Value::Number(4.0));assert_eq!(r.execute("Math.floor(3.9);").unwrap(),Value::Number(3.0));assert_eq!(r.execute("Math.ceil(3.1);").unwrap(),Value::Number(4.0));assert_eq!(r.execute("Math.sqrt(81);").unwrap(),Value::Number(9.0));assert_eq!(r.execute("Math.pow(2,5);").unwrap(),Value::Number(32.0));assert_eq!(r.execute("Math.max(1,7,3);").unwrap(),Value::Number(7.0));assert_eq!(r.execute("Math.min(1,7,3);").unwrap(),Value::Number(1.0));}#[test]fn string_replace_all_replaces_every_occurrence(){let mut r=Runtime::new();assert_eq!(r.execute("\"one fish two fish\".replaceAll(\"fish\",\"cat\");").unwrap(),Value::String("one cat two cat".into()));assert_eq!(r.execute("\"aaa\".replaceAll(\"a\",\"b\");").unwrap(),Value::String("bbb".into()));assert_eq!(r.execute("\"abc\".replaceAll(\"\",\"-\");").unwrap(),Value::String("-a-b-c-".into()));}
#[test]fn string_character_and_replace_methods(){let mut r=Runtime::new();assert_eq!(r.execute("\"hello\".charAt(1);").unwrap(),Value::String("e".into()));assert_eq!(r.execute("\"hello\".replace(\"ll\",\"y\");").unwrap(),Value::String("heyo".into()));assert_eq!(r.execute("\"hello\".substring(1,4);").unwrap(),Value::String("ell".into()));assert_eq!(r.execute("\"hello\".charCodeAt(0);").unwrap(),Value::Number(104.0));}#[test]fn conversion_and_numeric_builtins(){let mut r=Runtime::new();assert_eq!(r.execute("Number(\"12\");").unwrap(),Value::Number(12.0));assert_eq!(r.execute("String(42);").unwrap(),Value::String("42".into()));assert_eq!(r.execute("Boolean(0);").unwrap(),Value::Boolean(false));assert_eq!(r.execute("parseInt(\"27px\");").unwrap(),Value::Number(27.0));assert_eq!(r.execute("parseFloat(\"3.5rem\");").unwrap(),Value::Number(3.5));assert_eq!(r.execute("isNaN(Number(\"no\"));").unwrap(),Value::Boolean(true));assert_eq!(r.execute("isFinite(10);").unwrap(),Value::Boolean(true));assert_eq!(r.execute("typeof missingVariable;").unwrap(),Value::String("undefined".into()));}#[test]fn delete_operator(){let mut r=Runtime::new();assert_eq!(r.execute("let o={x:1};delete o.x;").unwrap(),Value::Boolean(true));assert_eq!(r.execute("\"x\" in o;").unwrap(),Value::Boolean(false));assert_eq!(r.execute("let a=[1,2];delete a[0];").unwrap(),Value::Boolean(true));assert_eq!(r.execute("a.length;").unwrap(),Value::Number(2.0));assert_eq!(r.execute("a[0];").unwrap(),Value::Undefined);}#[test]fn in_operator(){let mut r=Runtime::new();assert_eq!(r.execute("\"x\" in {x:1};").unwrap(),Value::Boolean(true));assert_eq!(r.execute("\"y\" in {x:1};").unwrap(),Value::Boolean(false));assert_eq!(r.execute("0 in [4,5];").unwrap(),Value::Boolean(true));assert_eq!(r.execute("2 in [4,5];").unwrap(),Value::Boolean(false));assert_eq!(r.execute("\"length\" in [4];").unwrap(),Value::Boolean(true));assert!(r.execute("\"x\" in 3;").is_err());}#[test]fn nullish_coalescing(){let mut r=Runtime::new();assert_eq!(r.execute("null ?? 7;").unwrap(),Value::Number(7.0));assert_eq!(r.execute("undefined ?? 8;").unwrap(),Value::Number(8.0));assert_eq!(r.execute("0 ?? 9;").unwrap(),Value::Number(0.0));assert_eq!(r.execute("false ?? true;").unwrap(),Value::Boolean(false));assert_eq!(r.execute("let x=0;4 ?? (x=1);x;").unwrap(),Value::Number(0.0));}#[test]fn compound_property_assignments(){let mut r=Runtime::new();assert_eq!(r.execute("let o={x:2};o.x+=3;o.x*=4;o.x;").unwrap(),Value::Number(20.0));assert_eq!(r.execute("let a=[2];a[0]+=5;a[0];").unwrap(),Value::Number(7.0));}#[test]fn compound_assignments(){let mut r=Runtime::new();assert_eq!(r.execute("let x=10;x+=5;x-=2;x*=3;x/=2;x%=7;x;").unwrap(),Value::Number(5.5));let mut r=Runtime::new();assert_eq!(r.execute("let s=\"hi\";s+=\"!\";s;").unwrap(),Value::String("hi!".into()));}#[test]fn compound_assignment_const_is_error(){let mut r=Runtime::new();assert!(r.execute("const x=1;x+=1;").is_err());}#[test]fn increment_and_decrement(){let mut r=Runtime::new();assert_eq!(r.execute("let x=2; x++; ++x; x--; --x; x;").unwrap(),Value::Number(2.0));let mut r=Runtime::new();assert_eq!(r.execute("let x=3; x++;").unwrap(),Value::Number(3.0));assert_eq!(r.execute("let x=3; ++x;").unwrap(),Value::Number(4.0));}#[test]fn increment_string_uses_numeric_result(){let mut r=Runtime::new();assert_eq!(r.execute("let x=\"2\";x++;").unwrap(),Value::Number(2.0));assert_eq!(r.execute("x;").unwrap(),Value::Number(3.0));}#[test]fn increment_const_is_error(){let mut r=Runtime::new();assert!(r.execute("const x=1; x++;").is_err());}#[test]fn functions(){let mut r=Runtime::new();assert_eq!(r.execute("function add(a,b){return a+b;}add(2,5);").unwrap(),Value::Number(7.0))}#[test]fn arrays_and_mutation(){let mut r=Runtime::new();assert_eq!(r.execute("let a=[3,4];a[1]=9;a[0]+a[1];").unwrap(),Value::Number(12.0))}#[test]fn object_properties(){let mut r=Runtime::new();assert_eq!(r.execute("let o={x:4, name:'hi'};o.x=7;o.x;").unwrap(),Value::Number(7.0));assert_eq!(r.execute("o['name'];").unwrap(),Value::String("hi".into()))}#[test]fn array_length(){let mut r=Runtime::new();assert_eq!(r.execute("let a=[1,2,3];a.length;").unwrap(),Value::Number(3.0))}#[test]fn typeof_operator(){let mut r=Runtime::new();assert_eq!(r.execute("typeof 1;").unwrap(),Value::String("number".into()));assert_eq!(r.execute("typeof \"x\";").unwrap(),Value::String("string".into()));assert_eq!(r.execute("typeof true;").unwrap(),Value::String("boolean".into()));assert_eq!(r.execute("typeof undefined;").unwrap(),Value::String("undefined".into()));assert_eq!(r.execute("typeof null;").unwrap(),Value::String("object".into()));}#[test]fn void_operator(){let mut r=Runtime::new();assert_eq!(r.execute("void 123;").unwrap(),Value::Undefined);assert_eq!(r.execute("let x=0;void (x=5);x;").unwrap(),Value::Number(5.0));}#[test]fn conditional_operator(){let mut r=Runtime::new();assert_eq!(r.execute("true ? 4 : 9;").unwrap(),Value::Number(4.0));assert_eq!(r.execute("false ? 4 : 9;").unwrap(),Value::Number(9.0));assert_eq!(r.execute("let x=0;true ? 7 : (x=1);x;").unwrap(),Value::Number(0.0));}#[test]fn array_methods(){let mut r=Runtime::new();assert_eq!(r.execute("let a=[1];a.push(2);a.length;").unwrap(),Value::Number(2.0));assert_eq!(r.execute("a.includes(2);").unwrap(),Value::Boolean(true));assert_eq!(r.execute("a.indexOf(2);").unwrap(),Value::Number(1.0));assert_eq!(r.execute("a.pop();").unwrap(),Value::Number(2.0));assert_eq!(r.execute("a.length;").unwrap(),Value::Number(1.0));}#[test]fn string_methods(){let mut r=Runtime::new();assert_eq!(r.execute('"abc".toUpperCase();').unwrap(),Value::String("ABC".into()));assert_eq!(r.execute('"abc".includes("b");').unwrap(),Value::Boolean(true));}#[test]fn additional_array_methods(){let mut r=Runtime::new();assert_eq!(r.execute("let a=[1,2,3];a.reverse();a.join(\"-\");").unwrap(),Value::String("3-2-1".into()));}#[test]fn additional_string_methods(){let mut r=Runtime::new();assert_eq!(r.execute("\"  hi  \".trim();").unwrap(),Value::String("hi".into()));assert_eq!(r.execute("\"hello\".startsWith(\"he\");").unwrap(),Value::Boolean(true));assert_eq!(r.execute("\"hello\".endsWith(\"lo\");").unwrap(),Value::Boolean(true));}#[test]fn do_while_runs_body_before_condition(){let mut r=Runtime::new();assert_eq!(r.execute("let x=0;do{x=x+1;}while(x<3);x;").unwrap(),Value::Number(3.0));assert_eq!(r.execute("let y=0;do{y=7;}while(false);y;").unwrap(),Value::Number(7.0));}#[test]fn classic_for_loop(){let mut r=Runtime::new();assert_eq!(r.execute("let sum=0;for(let i=0;i<5;i=i+1){sum=sum+i;}sum;").unwrap(),Value::Number(10.0));}#[test]fn for_loop_optional_clauses(){let mut r=Runtime::new();assert_eq!(r.execute("let i=0;for(;i<3;){i=i+1;}i;").unwrap(),Value::Number(3.0));}#[test]fn break_in_for_loop(){let mut r=Runtime::new();assert_eq!(r.execute("let i=0;for(;i<10;i=i+1){if(i===4){break;}}i;").unwrap(),Value::Number(4.0));}#[test]fn continue_in_for_loop_runs_update(){let mut r=Runtime::new();assert_eq!(r.execute("let sum=0;for(let i=0;i<5;i=i+1){if(i===2){continue;}sum=sum+i;}sum;").unwrap(),Value::Number(8.0));}#[test]fn continue_in_while_loop(){let mut r=Runtime::new();assert_eq!(r.execute("let i=0;let sum=0;while(i<4){i=i+1;if(i===2){continue;}sum=sum+i;}sum;").unwrap(),Value::Number(8.0));}#[test]fn break_outside_loop_is_error(){let mut r=Runtime::new();assert!(r.execute("break;").is_err());}#[test]fn continue_outside_loop_is_error(){let mut r=Runtime::new();assert!(r.execute("continue;").is_err());}#[test]fn statements_after_loop_control_are_not_skipped(){let mut r=Runtime::new();assert_eq!(r.execute("let x=0;while(true){x=1;break;x=9;}x;").unwrap(),Value::Number(1.0));}#[test]fn shared_reference(){let mut r=Runtime::new();assert_eq!(r.execute("let a=[1];let b=a;b[0]=8;a[0];").unwrap(),Value::Number(8.0))}#[test]fn named_function_expression_recurses_without_leaking_its_name(){let mut r=Runtime::new();assert_eq!(r.execute("let factorial = function inner(n) { if (n <= 1) { return 1; } return n * inner(n - 1); }; factorial(6);").unwrap(),Value::Number(720.0));assert!(matches!(r.execute("inner;"),Err(EngineError::Reference(_))));}
#[test]fn arrow_functions_support_single_parameters_and_closures(){let mut r=Runtime::new();assert_eq!(r.execute("let offset = 7; let addOffset = x => x + offset; addOffset(5);").unwrap(),Value::Number(12.0));assert_eq!(r.execute("let sum = (a, b) => a + b; sum(2, 9);").unwrap(),Value::Number(11.0));}
#[test]fn function_name_and_length_properties(){let mut r=Runtime::new();assert_eq!(r.execute("(function named(a,b,...rest) { return a; }).name;").unwrap(),Value::String("named".into()));assert_eq!(r.execute("(function named(a,b,...rest) { return a; }).length;").unwrap(),Value::Number(2.0));assert_eq!(r.execute("(x => x).name;").unwrap(),Value::String("".into()));assert_eq!(r.execute("(x => x).length;").unwrap(),Value::Number(1.0));}
